 shadow(parent,size=1){const canvas=document.createElement('canvas');canvas.width=canvas.height=64;const c=canvas.getContext('2d'),g=c.createRadialGradient(32,32,0,32,32,32);g.addColorStop(0,'rgba(37,72,58,.32)');g.addColorStop(1,'rgba(37,72,58,0)');c.fillStyle=g;c.fillRect(0,0,64,64);const m=new T.Mesh(new T.PlaneGeometry(size*2,size*1.4),new T.MeshBasicMaterial({map:new T.CanvasTexture(canvas),transparent:true,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.y=.04;parent.add(m);}
