 lamp(x,z){const g=this.group(x,0,z);this.cylinder(.09,.14,3.1,'#65866e',g,0,1.55,0,8);this.ball(.32,'#fff2a3',g,0,3.2,0,1,1.2,1);this.mesh(new T.ConeGeometry(.5,.4,8),'#5d927c',g,0,3.6,0);}
 building(x,z,w,d,color,roof,title,type='house',h=3.6){const g=this.group(x,0,z);this.box(w+.45,.38,d+.45,'#e8dbc2',g,0,.2,0);this.box(w,h,d,color,g,0,h/2+.35,0);const r=this.mesh(new T.ConeGeometry(1,1,4),roof,g,0,h+1.45,0);r.rotation.y=Math.PI/4;r.scale.set(w*.81,2.3,d*.81);this.box(w+.7,.18,d+.7,roof,g,0,h+.48,0);this.box(1.1,2.2,.12,'#a17956',g,0,1.5,d/2+.08);this.ball(.065,'#f7d275',g,.33,1.45,d/2+.18);[-1,1].forEach(a=>{this.box(1.05,1.2,.14,'#fff3d5',g,a*w*.3,2.25,d/2+.09);this.box(.78,.92,.15,'#a4d2d0',g,a*w*.3,2.25,d/2+.18);this.box(.06,.98,.18,'#fff6df',g,a*w*.3,2.25,d/2+.27);this.box(.82,.06,.18,'#fff6df',g,a*w*.3,2.25,d/2+.27);this.box(1.3,.2,.48,'#eec09b',g,a*w*.3,1.55,d/2+.22);});this.box(1.55,.2,.8,'#f1e4cc',g,0,.35,d/2+.4);if(title)this.sign(title,0,h+3.1,0,w+2,g);if(type==='office'){this.cylinder(.06,.09,5.3,'#e9e9d9',g,-w/2-.6,2.8,0);this.box(1.3,.8,.05,'#faf7e5',g,-w/2+.03,4.8,0);this.ball(.24,'#df7978',g,-w/2+.02,4.8,.05,1,.75,.2);this.box(3.7,.7,.2,'#547b70',g,0,h-.3,d/2+.12);this.sign('조달청',0,h-.25,d/2+.4,3,g,'#e5f0da');}this.blocks.push({x,z,w:w+.5,d:d+.5});return g;}
