  this.building(-13,-10,7.8,5.7,'#f6edd3','#86b3a1','첫손님 출장소','office',4.4);this.building(-16,9,6.4,4.8,'#f7e5bf','#a9b9d2','','house',3.7);this.institutionSign=this.sign('솔솔소방서',-16,6,9,8);
