  for(const [x,z]of[[-23,9],[-23,-12],[21,-8],[22,4],[-8,14],[7,-20]]){const bed=this.group(x,0,z);this.box(3.2,.25,1.1,'#a28d64',bed,0,.2,0);for(let i=0;i<4;i++)this.ball(.55,'#689d71',bed,-1.1+i*.72,.5,0,1,.75,.8);}
  this.building(-17,46,4.5,3.5,'#e7bc9b','#b87871','', 'house',2.9);this.building(18,46,4.5,3.5,'#f0dbab','#7da6a0','', 'house',2.9);
